public void givenLoanSaleTransferable(final boolean isDelayedSettlementEnabled, final ExternalTransferStatus pendingStatus, final ExternalTransferStatus expectedActiveStatus) {
    // given
    final LoanProduct loanProduct = Mockito.mock(LoanProduct.class);
    when(loanProduct.getId()).thenReturn(LOAN_PRODUCT_ID);
    final Loan loanForProcessing = Mockito.mock(Loan.class);
    when(loanForProcessing.getId()).thenReturn(1L);
